  {
   "id": "FAM:SF-PAP-029",
   "status_as_recorded": "untestable",
   "finding": "An archived check of mover portability related to destination net-rating change was 'underpowered and null once corrected for landing-spot quality' (no numbers recorded)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-090",
   "what_failed": "Attempting to test connector diet x destination structural-gap match for connector movers.",
