   "code": "OUTCOME_DERIVED_LABEL",
   "text": "If 'role travel' is measured by a derived label (e.g., 'successful transfer'), the process of deriving this label must be robust and free from bias or leakage."
  },
  {
   "code": "BASE_RATE",
   "text": "The base rate of 'successful role transfer' might be low, making it difficult to detect differences between groups, especially with a small sample."
  }
 ],
